package com.wizzadrds.theworldremembers.behavior; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class NpcBehaviorStateTest{@Test void fatigueIsBounded(){var s=NpcBehaviorState.idle(0).fatigue(500,1);assertEquals(100,s.fatigue());assertEquals(0,s.stop(2).followTarget()==null?0:1);} @Test void followStoresTarget(){var id=UUID.randomUUID();assertEquals(id,NpcBehaviorState.idle(0).follow(id,1).followTarget());}}
